import React, { useState } from 'react';
import './styles/style.css'; // Zamiast używać importów z React Native, będziemy używać CSS
import { Link } from 'react-router-dom'; // do nawigacji w PWA
import ItemAdd from './ItemAdd';

interface ItemListProps {
  username: string;
  avatar: string;
  onLogout: () => void;
}

const ItemList: React.FC<ItemListProps> = ({ username, avatar, onLogout }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [showAddItem, setShowAddItem] = useState(false);
  const [activeMenu2, setActiveMenu2] = useState<number>(1);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    if (window.confirm('Czy na pewno chcesz się wylogować?')) {
      onLogout();
    }
  };

  const navigateToAddItem = () => {
    setShowAddItem(true);
    setIsMenuOpen(false);
  };

  const navigateToList = () => {
    setShowAddItem(false);
  };

  if (showAddItem) {
    return (
      <ItemAdd 
        username={username} 
        avatar={avatar} 
        onLogout={onLogout} 
        onNavigateToList={navigateToList} 
      />
    );
  }

  return (
    <div className="container">
      <div className="menu">
        <button className="menuIcon" onClick={toggleMenu}>
          <img src="./assets/menu.png" alt="Menu" />
        </button>
        <img src="./assets/skinradar.png" alt="Logo" className="logo" />
        <button className="avatarButton" onClick={toggleUserMenu}>
          <img src={avatar} alt="User Avatar" className="avatar" />
        </button>
      </div>

      <div className="scrollContainer">
        {isMenuOpen && (
          <div className="dropdownMenu">
            <button className="dropdownButton">
              <span className="dropdownButtonText">LISTA</span>
            </button>
            <button className="dropdownButton" onClick={navigateToAddItem}>
              <span className="dropdownButtonText">DODAJ</span>
            </button>
          </div>
        )}

        {isUserMenuOpen && (
          <div className="userMenu">
            <span className="userMenuText">{username}</span>
            <button className="logoutButton" onClick={handleLogout}>
              <img src="./assets/logout.png" alt="Logout" className="logoutIcon" />
            </button>
          </div>
        )}

        <div className="content">
          <h1 className="title">Witaj w aplikacji SkinRadar!</h1>
        </div>
      </div>

      <div className="menu2">
        {[
          './assets/settings.png',
          './assets/bell.png',
          './assets/questmark.png',
        ].map((icon, idx) => (
          <button
            key={idx}
            onClick={() => setActiveMenu2(idx)}
            className="menu2Button"
          >
            <div className={`menu2IconWrapper ${activeMenu2 === idx ? 'active' : ''}`}>
              <img
                src={icon}
                alt={`Icon ${idx}`}
                className={`menuButtonIcon ${activeMenu2 === idx ? 'active' : ''}`}
              />
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

export default ItemList;
